    public function getConges($agent, $start, $end)
    {
        $sql = "select distinct c 
                from AgentBundle:Conges c
                where (c.typeConges=1 and c.agent=:agent and (c.numCessation is not null) ) and (:start >= c.datedebut and  :end <= c.datefin)";

        $req = $this->getEntityManager()
            ->createQuery($sql)
            ->setParameter('agent', $agent)
            ->setParameter('start', $start)
            ->setParameter('end', $end)
            ->setMaxResults(1)
            ->getOneOrNullResult();


        return $req;
    }


    public function cumuldemandes($periode = null)
    {
        $sql1 = "SELECT t.libelle,
                  SUM(case when d.id is not null then 1 else 0 end) as nbre,
                  SUM(case when d.etatRepGrh = 1 then 1 Else 0 End) As TRAITE,
                  SUM(case when d.etatRepGrh <> 1 then 1 Else 0 End) As NONTRAITE
                     FROM DemandesBundle:TypeDemande t
                     LEFT JOIN DemandesBundle:Demande d WITH d.typeDemande = t.id
                     ";

        ////////////////
        $sql2 = "SELECT UPPER(t.libelle) As libelle, SUM(case when c.id is not null then 1 else 0 end) as nbre,
                                 SUM(case when c.etat in(1,3) then 1 Else 0 End) As TRAITE,
                                 SUM(case when c.etat = 0 then 1 Else 0 End) As NONTRAITE
                            FROM AgentBundle:TypeConges t
                              LEFT JOIN AgentBundle:Conges c WITH c.typeConges = t.id";


        if ($periode != null) {
            $sql1 = $sql1 . " WHERE d.datecreation BETWEEN :debut and :fin ";
            $sql2 = $sql2 . " WHERE c.datecreation BETWEEN :debut and :fin ";
        }
        $sql1 = $sql1 . " GROUP BY t.libelle";
        $sql2 = $sql2 . " GROUP BY t.libelle";


        $autorisationabscence = $this->getEntityManager()
            ->createQuery($sql1);

        $autorisationabscence1 = $this->getEntityManager()
            ->createQuery($sql2);
        if ($periode != null) {
            $autorisationabscence = $autorisationabscence->setParameter('debut', new \DateTime($periode['debut']))->setParameter('fin', new \DateTime($periode['fin']));
            $autorisationabscence1 = $autorisationabscence1->setParameter('debut', new \DateTime($periode['debut']))->setParameter('fin', new \DateTime($periode['fin']));
        }
        $autorisationabscence = $autorisationabscence->getResult();
        $autorisationabscence1 = $autorisationabscence1->getResult();
        //dump(array_merge($autorisationabscence, $autorisationabscence1) );
        return array_merge($autorisationabscence, $autorisationabscence1);
    }

    public function getNbre($type, $matricule)
    {
        if ($type == 1) {
            return $this->createQueryBuilder('d')
                ->select('COUNT(d)')
                ->where('d.typeDemande = :Type')
                ->andWhere('d.emmeteur = :Matricule')
                ->andWhere('d.etatRepGrh = 1')
                ->setParameter('Matricule', $matricule)
                ->setParameter('Type', $type)
                ->getQuery()
                ->getSingleScalarResult();
        } elseif ($type > 1) {
            return $this->createQueryBuilder('d')
                ->select('COUNT(d)')
                ->where('d.typeDemande = :Type')
                ->andWhere('d.emmeteur = :Matricule')
                ->andWhere('d.etatRepGrh = 1')
                ->setParameter('Matricule', $matricule)
                ->setParameter('Type', $type)
                ->getQuery()
                ->getSingleScalarResult();
        }
    }

    public function DemandeEncours($type, $matricule)
    {
        //var_dump($matricule);
        if ($type == 1) {
            $qb = $this->createQueryBuilder('d')
                ->where('d.typeDemande = :Type AND d.emmeteur = :Matricule AND d.etatRepSupDir <= 1 AND d.etatRepSupDir2 <= 1 AND d.etatRepGrh < 1')
                ->setParameter('Type', $type)
                ->setParameter('Matricule', $matricule);
        } else {
            $qb = $this->createQueryBuilder('d')
                ->where('d.typeDemande = :Type AND d.emmeteur = :Matricule AND d.etatRepGrh < 1')
                ->setParameter('Type', $type)
                ->setParameter('Matricule', $matricule);
        }
        return $qb->getQuery()->getResult();
    }

