    //autres services
    public function findDemandeReceiveold($role = null, $todo = null, $user = null, $type = null, $deleguation = ['retour' => 2, 'service' => null], $etatImprimer = null)
    {
        //dump($etatImprimer); die;
        $qb = $this->createQueryBuilder('d')
            ->join('d.emmeteur', 'e')
            ->leftjoin('d.SupDir', 's1')
            ->leftjoin('d.SupDir2', 's2')
            ->addSelect('e');
        //$role
        //1: Role RH
        //2: Role Respo
        //role RH


        if ($role == 1) {

            //attente autorisation absence
            if ($todo == 1) {
                $qb->Where("d.etatRepSupDir2 = 1 and d.etatRepGrh = 0 and d.typeDemande = 1")
                    ->orWhere("(d.SupDir = 326 or d.SupDir2 = 326) and d.typeDemande = 1 and d.etatRepGrh = 0 and d.etatEncours != 1");
            } //attente autres demandes
            elseif ($todo == 2) {
                $qb->Where("d.etatRepGrh = 0 and d.typeDemande = :Type")
                    ->setParameter("Type", $type);
            } //archive; possibilte d'ajouter la condition de la date pour l'archive
            elseif ($todo == 3) {
                $qb->Where("d.etatRepSupDir2 = 1 and d.etatRepGrh > 0")
                    ->orWhere("d.etatRepGrh > 0 and d.typeDemande > 1");
            } //impression actes
            elseif ($todo == 4) {
                $qb->Where("d.etatRepGrh = 1 and d.signeActe = 0")->andWhere($qb->expr()->In('d.typeDemande', ':Type'))
                    ->setParameter("Type", $type);
            }
            //numerisation actes
            elseif ($todo == 5) {
                $qb->Where("d.etatRepGrh = 1 and d.typeDemande = :Type and d.signeActe = 0")
                    ->setParameter("Type", $type);
            }
            if ($deleguation['service'] and $deleguation['retour'] == 0) {
                $qb->andWhere($qb->expr()->In('e.Direction', ':sercice'))
                    ->setParameter('sercice', explode(",", $deleguation['service']));
            }

            if ($etatImprimer) {

                $qb->andWhere('d.etatImpression = :etat')->setParameter('etat', $etatImprimer);
            }
            //die;
            //role_respo
        } elseif ($role == 2) {

            //en attente
            if ($todo == 1) {
                if ($deleguation['service'] and $deleguation['retour'] == 0) {
                    $qb->where('d.etatRepSupDir = 0 or (d.etatRepSupDir2 = 0 and d.etatRepSupDir <= 1)')
                        ->andWhere($qb->expr()->In('e.Direction', ':sercice'))
                        ->setParameter('sercice', explode(",", $deleguation['service']));
                } else {
                    $qb->Where("d.SupDir = :Agent and d.etatRepSupDir = 0")
                        ->orWhere("d.SupDir2 = :Agent and d.etatRepSupDir2 = 0 and d.etatRepSupDir <= 1")
                        ->setParameter("Agent", $user->getAgent());
                }
            } //archive
            elseif ($todo == 2) {
                if ($deleguation['service'] and $deleguation['retour'] == 0) {
                    $qb->where('d.etatRepSupDir > 0 or d.etatRepSupDir2 > 0')
                        ->andWhere($qb->expr()->In('e.Direction', ':sercice'))
                        ->setParameter('sercice', explode(",", $deleguation['service']));
                } else {
                    $qb->Where("d.SupDir = :Agent and d.etatRepSupDir > 0")
                        ->orWhere("d.SupDir2 = :Agent and d.etatRepSupDir2 > 0")
                        ->setParameter("Agent", $user->getAgent());
                }
            }
        }

        $qb->orderBy('d.datecreation', 'DESC');

        return $qb->getQuery()->getResult();
    }

    public function demandeSendAutorisation($matricule)
    {
        $qb = $this->createQueryBuilder('d')
            ->join('d.emmeteur', 'e')
            ->addSelect('d')
            ->where("e.matricule = :Matricule")
            ->andWhere("d.typeDemande = 1")
            ->setParameter("Matricule", $matricule)
            ->orderBy('d.datecreation', 'DESC');
        return $qb->getQuery()->getResult();
    }

    public function demandeSendOther($matricule)
    {
        $qb = $this->createQueryBuilder('d')
            ->join('d.emmeteur', 'e')
            ->addSelect('d')
            ->where("e.matricule = :Matricule")
            ->andWhere("d.typeDemande != 1")
            ->setParameter("Matricule", $matricule)
            ->orderBy('d.datecreation', 'DESC');
        return $qb->getQuery()->getResult();
    }

    public function notification($Direction, $user)
    {
        $Matricule = $user->getAgent()->getMatricule();

        if ($user->hasRole("ROLE_AGENT")) {
            $send = $this->createQueryBuilder('d')
                ->join('d.emmeteur', 'e')
                ->addSelect('e')
                ->where("e.matricule = :Matricule")
                ->andWhere("d.etatEmmission != 0")
                ->andWhere("d.etatNotification = 0")
                ->setParameter("Matricule", $Matricule)
                ->orderBy('d.datecreation', 'DESC');
            return $send->getQuery()->getResult();
        } elseif ($user->hasRole("ROLE_RESPO")) {
            $send = $this->createQueryBuilder('d')
                ->join('d.emmeteur', 'e')
                ->addSelect('e')
                ->Where("e.Direction = :Direction AND d.etatRepSupDir = 0 AND d.typeDemande = 1")
                ->orWhere("e.matricule = :Matricule AND d.etatEmmission != 0 AND d.etatNotification = 0")
                ->setParameter("Direction", $Direction)
                ->setParameter("Matricule", $Matricule)
                ->orderBy('d.datecreation', 'DESC');
            return $send->getQuery()->getResult();
            // $receive2="";
        } elseif ($user->hasRole("ROLE_RESPO_SRHMG")) {
            /*
              $receive1 = $this->createQueryBuilder('d')
              ->join('d.emmeteur', 'e')
              ->addSelect('e')
              ->Where("e.Direction = :Direction")
              ->andWhere("d.etatRepSupDir = 0")
              ->andWhere("d.typeDemande = 1")
              ->setParameter("Direction", $Direction)
              ->orderBy('d.datecreation', 'DESC');
              $receive1->getQuery()->getResult();
             */
            $send = $this->createQueryBuilder('d')
                ->join('d.emmeteur', 'e')
                ->addSelect('e')
                //Autres Autorisation
                ->Where("d.etatRepSupDir = 0 AND d.etatRepGrh IS NULL AND d.typeDemande != 1")
                //Autorisation Absence des autres service validation au niveau 2
                ->orWhere("d.etatRepSupDir = 1 AND d.etatRepGrh = 0  AND d.typeDemande = 1")
                //Autorisation Absence de son service validation Niveau 1
                ->orWhere("e.Direction = :Direction AND d.etatRepSupDir = 0 AND d.typeDemande = 1")
                //Propre Notification
                ->orWhere("e.matricule = :Matricule AND d.etatEmmission != 0 AND d.etatNotification = 0")
                ->setParameter("Direction", $Direction)
                ->setParameter("Matricule", $Matricule)
                ->orderBy('d.datecreation', 'DESC');
            return $send->getQuery()->getResult();
        } else { }
    }

    public function nbreDemande($mat)
    {
        $qb = $this->createQueryBuilder('d')
            ->select('COUNT(d) as compt, t.libelle')
            ->join('d.typeDemande', 't')
            //->addSelect('e')
            ->where("d.emmeteur = :Matricule")
            ->groupBy('d.typeDemande, t.libelle')
            ->setParameter("Matricule", $mat);
        return $qb->getQuery()->getResult();
    }

    public function listPrint($type)
    {
        switch ($type) {
            case 1:
                # code...
                $qb = $this->createQueryBuilder('d')
                    ->where('d.typeDemande = 1')
                    ->andWhere('d.etatRepSupDir = 1')
                    ->andWhere('d.etatRepGrh = 1')
                    ->orderBy('d.datecreation', 'DESC');
                return $qb->getQuery()->getResult();
                break;
            case 3:
                $qb = $this->createQueryBuilder('d')
                    ->where('d.typeDemande = 3')
                    ->andWhere('d.etatRepGrh = 1')
                    ->orderBy('d.datecreation', 'DESC');
                return $qb->getQuery()->getResult();
                break;

            case 4:
                $qb = $this->createQueryBuilder('d')
                    ->where('d.typeDemande = 4')
                    ->andWhere('d.etatRepGrh = 1')
                    ->orderBy('d.datecreation', 'DESC');
                return $qb->getQuery()->getResult();
                break;

            default:
                # code...
                $qb = $this->createQueryBuilder('d')
                    ->where('d.typeDemande > 1')
                    ->andWhere('d.etatRepGrh = 1')
                    ->orderBy('d.datecreation', 'DESC');
                return $qb->getQuery()->getResult();
                break;
        }
    }

    public function statsdemande()
    {
        $critere = null;
        //demandes
        $qb = $this->createQueryBuilder('d')
            ->join('d.typeDemande', 't')
            ->leftjoin('AgentBundle:Agent', 'a', Join::WITH, "d.emmeteur = a.matricule and a.code_dg = 'DG0001' and a.code_dc='DC0003' and d.etatEncours = 0")
            ->leftjoin('AgentBundle:Agent', 'b', Join::WITH, "d.emmeteur = b.matricule and b.code_dg = 'DG0001' and b.code_dc<>'DC0003' and d.etatEncours = 0 and d.etatRepGrh = 0 and d.etatRepSupDir = 1 and d.etatRepSupDir2 = 1 ")
            ->where(" (length(b.matricule) > 0 ) ")
            ->orWhere(" (length(a.matricule) > 0 ) ")
            ->groupBy('d.typeDemande, t.libelle, d.emmeteur ');

        return $qb->getQuery()->getResult();
    }

    public function statsmutation()
    {
        $critere = null;
        //mutation
        $qb = $this->getEntityManager()->createQueryBuilder()
            ->select("aff ")
            ->from('AgentBundle:Mutation', 'aff')
            ->where('aff.TypeMutation =:TypeMutation')
            ->andWhere('aff.Grh is null')
            ->setParameter('TypeMutation', 1);


        return $qb->getQuery()->getResult();
    }

    public function findexceptabscence($users)
    {
        $qb = $this->getEntityManager()->createQueryBuilder()
            ->select("d ")
            ->from('DemandesBundle:Demande', 'd')
            ->join('d.typeDemande', 't')
            ->where('t.etat =:etat')
            ->setParameter('etat', 1);
        if ($users->hasRole('ROLE_SAAF')) {
            $qb = $qb->andWhere('d.avis is not null');
        }
        $qb = $qb->orderBy('d.datecreation', 'DESC');

        return $qb->getQuery()->getResult();
    }

