                } else {

                    $qb->Where($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir > 0 and " . $niveau . " = 1")
                        ->orWhere($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir2 > 0  and " . $niveau . " = 2")
                        ->setParameter('service', $user->getAgent()->getServiceActuel());
                }
            }
        }
        //die;
        $qb->orderBy('d.datecreation', 'DESC');

        return $qb->getQuery()->getResult();
    }

    public function findDemandeReceive($role = null, $todo = null, $user = null, $type = null, $deleguation = ['retour' => 2, 'service' => null], $etatImprimer = null, $niveau = null)
    {

        $niveau = $user->getAgent()->getServiceActuel(1);
        $qb = $this->createQueryBuilder('d')
            ->join('d.emmeteur', 'e')
            ->join('d.positionnement', 'p')
            ->addSelect('e');
        //$role
        //1: Role RH
        //2: Role Respo
        //role RH


        if ($role == 1) {
            //die;
            //attente autorisation absence
            if ($todo == 1) {
                $qb->Where("d.etatRepSupDir2 = 1 and d.etatRepGrh = 0 and d.typeDemande = 1");
            } //attente autres demandes
            elseif ($todo == 2) {
                $qb->Where("d.etatRepGrh = 0 and d.typeDemande = :Type")
                    ->setParameter("Type", $type);
            } //archive; possibilte d'ajouter la condition de la date pour l'archive
            elseif ($todo == 3) {
                $qb->Where("d.etatRepSupDir2 = 1 and d.etatRepGrh > 0")
                    ->orWhere("d.etatRepGrh > 0 and d.typeDemande > 1");
            } //impression actes
            elseif ($todo == 4) {
                $qb->Where("d.etatRepGrh = 1 and d.signeActe = 0")->andWhere($qb->expr()->In('d.typeDemande', ':Type'))
                    ->setParameter("Type", $type);
            }
            //numerisation actes
            elseif ($todo == 5) {
                $qb->Where("d.etatRepGrh = 1 and d.typeDemande = :Type and d.signeActe = 0")
                    ->setParameter("Type", $type);
            }
            //demandes cabinet et responsable
            elseif ($todo == 6) {
                //dump($type);die;
                //echo 4;die;
                $qb->where("d.etatRepSupDir <> 2 and d.etatRepSupDir2 <> 2 and d.etatRepGrh <> 2")
                    ->andWhere("d.etatRepGrh = 0 and d.typeDemande = :Type and p.Direction in (10,11,14,15,16,17,18,19) and d.etatRepGrh = 0")
                    ->orWhere("(d.etatRepSupDir <> 2 and d.etatRepSupDir2 <> 2 and d.etatRepGrh <> 2) and (e.Fonction in (5,8,9) and d.etatRepGrh = 0 and d.typeDemande = :Type)")
                    ->setParameter("Type", $type);
            }
            if ($deleguation['service'] and $deleguation['retour'] == 0) {
                $qb->andWhere($qb->expr()->In('e.Direction', ':sercice'))
                    ->setParameter('sercice', explode(",", $deleguation['service']));
            }

            if ($etatImprimer) {

                $qb->andWhere('d.etatImpression = :etat')->setParameter('etat', $etatImprimer);
            }

            //die;
            //role_respodie;
        } elseif ($role == 2) {

            //en attente

            if ($todo == 1) {
                if ($deleguation['service'] and $deleguation['retour'] == 0) {
                    $qb
                        ->where('d.etatRepSupDir = 0 or (d.etatRepSupDir2 = 0 and d.etatRepSupDir <= 1)')
                        ->andWhere($qb->expr()->In('e.Direction', ':sercice'))
                        ->setParameter('sercice', explode(",", $deleguation['service']));
                } else {

                    $qb
                        ->where($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir = 0 and " . $niveau . " = 1")
                        ->orWhere($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir2 = 0 and d.etatRepSupDir <= 1 and " . $niveau . " = 2")
                        ->orWhere($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir2 = 0 and d.etatRepSupDir <= 1 and " . $niveau . " = 3 and p.Direction in (10,11,14,15,16,17,18,19)")
                        ->orWhere("e.Fonction in (5,8,9) and d.etatRepGrh = 0 and d.typeDemande = 1 and " . $niveau . " = 3")
                        ->setParameter('service', $user->getAgent()->getServiceActuel());

                    // dump($qb->getQuery()); die;
                }
            } //archive
            elseif ($todo == 2) {
                if ($deleguation['service'] and $deleguation['retour'] == 0) {
                    $qb->where('d.etatRepSupDir > 0 or d.etatRepSupDir2 > 0')
                        ->andWhere($qb->expr()->In('e.Direction', ':sercice'))
                        ->setParameter('sercice', explode(",", $deleguation['service']));
                } else {

                    $qb->Where($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir > 0 and " . $niveau . " = 1")
                        ->orWhere($user->getAgent()->getServiceActuelWhere("p", 'service') . " and d.etatRepSupDir2 > 0  and " . $niveau . " = 2")
                        ->setParameter('service', $user->getAgent()->getServiceActuel());
                }
            }
        }
        // dump($qb->getQuery()->getSQL());die;
        $qb->orderBy('d.datecreation', 'DESC');

        return $qb->getQuery()->getResult();
    }
    public function findInit($user)
    {
        $agent = $user->getAgent();
        $type = [6, 7];
        $qb = $this->createQueryBuilder('d');
        //->join('d.typeDemande', 't')
        $qb->join('d.avis', 'a')
            ->where('a.agent = :saaf')
            ->andWhere($qb->expr()->notIn('d.typeDemande', ':type'))
            ->setParameter('saaf', $agent)
            ->setParameter('type', $type)
            ->orderBy('d.datecreation', 'DESC');
        return $qb->getQuery()->getResult();
    }

    public function findEnAbsence($user, $natreq = 0, $mois = 0)
    {
        /*         * ********************************* */
        $infoService = ($user->getAgent()->retour_service());
        //Tableau de l'arborscence des service de l'agent
        $TabServ = explode(',', $infoService['tab_imput']);
        //Code Service de l'agent
        $serviceId = $infoService['service'];
        //Libellé du Service
        $niveau = count($TabServ) - 1;
        $now = new \Datetime();

        /*         * ********************************* */
        $qb = $this->createQueryBuilder('c') //c pour dire demande, juste de la paresse
            ->join('c.emmeteur', 'a');

        switch ($natreq) {
            case 0: //FindEnConge
                //pour Congé
                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                    ->andWhere("c.dateDeb <= :now")
                    ->andWhere("c.dateFin >= :now")
                    ->andWhere("c.etatRepGrh in (1)")
                    ->orderBy('c.dateFin', 'ASC')
                    ->setParameter("now", $now);
                $qb->setParameter("Direction", $user->getAgent()->getServiceActuel());




                break;
            case 1: //Find StatCongé
                //pour Congé
                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                    ->select('distinct Month(c.dateDeb) as mois, count(c.id) as total')
                    // ->andWhere("c.niveau = 0 ")
                    ->andWhere("Year(c.dateDeb)=:now")
                    ->andWhere("c.etatRepGrh in (1)")
                    ->groupBy("mois")
                    ->setParameter("now", date('Y')) //Année en cours
                    ->setParameter("Direction", $user->getAgent()->getServiceActuel());;
                break;
            case 2: //Find Details
                //pour Congé
                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                    // ->select('distinct Month(c.datedebut) as mois, count(distinct c.id) as total')
                    //->andWhere("c.niveau = 0 ")
                    ->andWhere("Year(c.dateDeb)=:now")
                    ->andWhere("Month(c.dateDeb)=:mois")
                    ->andWhere("c.etatRepGrh in (1)")
                    ->setParameter("now", date('Y'))
                    ->setParameter("mois", $mois)
                    ->setParameter("Direction", $user->getAgent()->getServiceActuel());
                break;
            case 3: //FindAvenir
                //pour congé
                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                    ->andWhere("c.dateDeb > :now")
                    ->andWhere("c.dateFin >= :now")
                    ->andWhere("c.etatRepGrh in (1)")
                    ->orderBy('c.dateDeb', 'ASC')
                    ->setParameter("now", $now);
                $qb->setParameter("Direction", $user->getAgent()->getServiceActuel());

                break;

            default:
                break;
        }


        return $qb->getQuery()->getResult();
    }
